using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using Impostors;
using Sandbox.Definitions;
using Sandbox.Game.Entities;
using Sandbox.Game.World;
using Shared.Config;
using Shared.Logging;
using VRage.Game;
using VRage.ModAPI;
using VRage.Voxels;
using VRageMath;

namespace Shared.Impostors;

// Asteroids the clients don't have by themselves. Procedural asteroids nobody edited are
// generated by every client within its view distance, the rest the server replicates only to
// about ViewDistance/√3 (MyVoxelReplicable). Planets are drawn by the game from afar anyway.
//
// Reading the voxels to hash them is about 40% of a build. So the source keeps the content hash
// of every asteroid nobody edited since it was last hashed (Known), and builds those from the
// hash alone: the pack or the shape cache has their shapes. Any change to the storage (mining,
// a voxel hand, a voxel reset) drops the asteroid's hash, so its next build reads the voxels
// again; after a reset they hash the same as before the edits and the pack's shapes are used
// again. An asteroid that was never edited (ContentChanged false) starts with the hash of its
// pack entry, if the pack was built before anybody edited it either. The known hashes are
// saved with the world, see Save.
public sealed class VoxelSource : ImpostorSource, IDisposable
{
    private const string KnownFile = "Impostors.asteroids";

    // Colors by the material's mined ore, the rest are stone. Stone is fitted to screenshots of
    // real asteroids from 8 directions (a neutral gray the 4 bit quantization keeps exact), the ores keep their hues at about the same brightness.
    private static readonly Dictionary<string, Vector3I> OreColors = new()
    {
        ["Stone"] = new Vector3I(170, 170, 170),
        ["Iron"] = new Vector3I(178, 144, 123),
        ["Nickel"] = new Vector3I(187, 180, 162),
        ["Cobalt"] = new Vector3I(128, 144, 183),
        ["Magnesium"] = new Vector3I(200, 200, 194),
        ["Silicon"] = new Vector3I(191, 191, 202),
        ["Silver"] = new Vector3I(204, 204, 208),
        ["Gold"] = new Vector3I(208, 174, 85),
        ["Platinum"] = new Vector3I(204, 208, 217),
        ["Uranium"] = new Vector3I(136, 166, 110),
        ["Ice"] = new Vector3I(200, 208, 217),
    };

    private static readonly Vector3I Stone = OreColors["Stone"];

    // Cells across the content at the coarsest level, at least
    private const int CoarsestCells = 6;

    private readonly IPluginConfig config;
    private readonly AsteroidPack pack;
    private readonly IPluginLogger log;

    // Storage edits seen per voxel map, the signature of its entry
    private readonly Dictionary<long, int> edits = new();

    // Content hash per voxel map, while nobody edited it since it was hashed. Builds on
    // background threads add to it, so both dictionaries are used under the lock.
    private readonly Dictionary<long, long> known = new();
    private readonly object sync = new();

    // Known hashes loaded with the world, for voxel maps not seen yet
    private readonly Dictionary<long, long> loaded;

    // Hash of what the shapes depend on besides the voxels: the material colors and the
    // occlusion setting. Known hashes, and the pack's hashes of unedited asteroids, are used
    // only with the same settings, else the cache would give shapes of the old ones.
    public readonly long Settings;

    public VoxelSource(IPluginConfig config, AsteroidPack pack, IPluginLogger log)
    {
        this.config = config;
        this.pack = pack;
        this.log = log;
        var settings = InputHash.Start((byte)ImpostorKind.Voxel);
        settings.Add(config.AsteroidOcclusion);
        foreach (var color in MaterialColors())
            settings.Add(color);
        Settings = settings.Value;
        if (pack != null && pack.Settings != Settings)
            log.Info(
                "The asteroid pack was built with other asteroid settings (occlusion, material colors), every asteroid is read to find its entry"
            );
        loaded = Load();
        MySession.Static.OnSavingCheckpoint += Save;
    }

    public void Dispose()
    {
        if (MySession.Static != null)
            MySession.Static.OnSavingCheckpoint -= Save;
    }

    // File in the world's folder: the game time of the save, Settings, then a line
    // per voxel map with its id and content hash. Taken only with the save it was written with: an older
    // backup of the world, or a world that crashed before its next save, may hold other voxels.
    private Dictionary<long, long> Load()
    {
        var result = new Dictionary<long, long>();
        var path = Path.Combine(MySession.Static.CurrentPath ?? "", KnownFile);
        try
        {
            if (!File.Exists(path))
                return result;
            var lines = File.ReadAllLines(path);
            if (lines.Length < 2 || lines[0] != SavedGameTime())
            {
                log.Info(
                    $"Asteroid hashes in {KnownFile} are from another save of the world, ignored"
                );
                return result;
            }
            if (lines[1] != Settings.ToString(CultureInfo.InvariantCulture))
            {
                log.Info($"Asteroid hashes in {KnownFile} are of other asteroid settings, ignored");
                return result;
            }
            foreach (var line in lines.Skip(2))
            {
                var parts = line.Split(' ');
                if (
                    parts.Length == 2
                    && long.TryParse(
                        parts[0],
                        NumberStyles.Integer,
                        CultureInfo.InvariantCulture,
                        out var id
                    )
                    && long.TryParse(
                        parts[1],
                        NumberStyles.Integer,
                        CultureInfo.InvariantCulture,
                        out var hash
                    )
                )
                    result[id] = hash;
            }
            log.Info($"Asteroid hashes: {result.Count} known from the last save");
        }
        catch (Exception e)
        {
            log.Warning(e, $"Failed to read {path}");
        }
        return result;
    }

    // The game time the loaded save was written at, from its Sandbox.sbc: the session's own has
    // run on since the load
    private static string SavedGameTime()
    {
        var path = Path.Combine(MySession.Static.CurrentPath ?? "", "Sandbox.sbc");
        var match = System.Text.RegularExpressions.Regex.Match(
            File.ReadAllText(path),
            "<ElapsedGameTime>(\\d+)</ElapsedGameTime>"
        );
        return match.Success ? match.Groups[1].Value : "";
    }

    // While the world saves, on the game thread: the hashes are those of the voxels being saved
    private void Save(MyObjectBuilder_Checkpoint checkpoint)
    {
        var path = Path.Combine(MySession.Static.CurrentPath ?? "", KnownFile);
        try
        {
            List<string> lines;
            lock (sync)
            {
                lines = known
                    .Select(k =>
                        k.Key.ToString(CultureInfo.InvariantCulture)
                        + " "
                        + k.Value.ToString(CultureInfo.InvariantCulture)
                    )
                    .ToList();
            }
            lines.Insert(0, Settings.ToString(CultureInfo.InvariantCulture));
            lines.Insert(0, checkpoint.ElapsedGameTime.ToString(CultureInfo.InvariantCulture));
            File.WriteAllLines(path, lines);
        }
        catch (Exception e)
        {
            log.Warning(e, $"Failed to write {path}");
        }
    }

    public override ImpostorKind Kind => ImpostorKind.Voxel;

    public override void Scan(ImpostorRegistry registry)
    {
        foreach (var entity in MyEntities.GetEntities())
        {
            if (
                entity is not MyVoxelMap map
                || map.Closed
                || map.MarkedForClose
                || map.Storage == null
            )
                continue;

            if (!map.Save && !map.ContentChanged && !map.BeforeContentChanged)
                continue;

            int signature;
            lock (sync)
            {
                if (!edits.ContainsKey(map.EntityId))
                {
                    edits[map.EntityId] = 0;
                    if (loaded.TryGetValue(map.EntityId, out var hash))
                        known[map.EntityId] = hash;
                    else if (
                        !map.ContentChanged
                        && pack != null
                        && pack.Settings == Settings
                        && pack.TryGetOriginal(map.EntityId, out hash)
                    )
                        known[map.EntityId] = hash;
                    map.RangeChanged += OnRangeChanged;
                }
                signature = edits[map.EntityId];
            }

            var entry = registry.Touch(map.EntityId, this);
            entry.Tag = map;
            entry.WorldMatrix = map.WorldMatrix;
            entry.WorldAabb = map.PositionComp.WorldAABB;
            entry.Velocity = Vector3.Zero;

            if (entry.Signature != signature)
            {
                entry.Signature = signature;
                entry.Stale = true;
            }
        }
    }

    // Game thread, or the thread of a voxel edit
    private void OnRangeChanged(
        MyVoxelBase voxel,
        Vector3I min,
        Vector3I max,
        MyStorageDataTypeFlags data
    )
    {
        lock (sync)
        {
            edits[voxel.EntityId] = edits.TryGetValue(voxel.EntityId, out var n) ? n + 1 : 1;
            known.Remove(voxel.EntityId);
        }
    }

    // Background thread: the content of this many edits hashes to this
    private void Hashed(long id, int edit, long input)
    {
        lock (sync)
        {
            if (edits.TryGetValue(id, out var n) && n == edit)
                known[id] = input;
        }
    }

    public override string Describe(ImpostorEntry entry) =>
        entry.Tag is MyVoxelMap { Storage: not null } map
            ? $"voxels={map.Storage.Size.X}x{map.Storage.Size.Y}x{map.Storage.Size.Z} occlusion={config.AsteroidOcclusion}"
            : "";

    // Colors by voxel material index, looked up on the game thread
    private static Vector3I[] MaterialColors()
    {
        var colors = new Vector3I[256];
        for (var i = 0; i < colors.Length; i++)
        {
            var material = MyDefinitionManager.Static.GetVoxelMaterialDefinition((byte)i);
            colors[i] =
                material?.MinedOre != null && OreColors.TryGetValue(material.MinedOre, out var c)
                    ? c
                    : Stone;
        }
        return colors;
    }

    public override Func<ShapeBuild, byte[][]> PrepareBuild(ImpostorEntry entry)
    {
        if (entry.Tag is not MyVoxelMap map || map.Closed || map.Storage == null)
            return null;

        var storage = map.Storage;
        var size = storage.Size;
        var corner = (Vector3)
            Vector3D.Transform(map.PositionLeftBottomCorner, MatrixD.Invert(map.WorldMatrix));

        var colors = MaterialColors();

        var occluded = config.AsteroidOcclusion;
        var id = map.EntityId;
        int edit;
        long knownInput;
        lock (sync)
        {
            edit = edits.TryGetValue(id, out var n) ? n : 0;
            known.TryGetValue(id, out knownInput);
        }
        return build =>
        {
            // Unedited since it was hashed: the pack or the cache has its shapes, unless the
            // cache dropped them or the occlusion setting changed since
            if (knownInput != 0)
            {
                var reused = build.Reuse(knownInput);
                if (reused != null)
                    return reused;
            }
            var shapes = Build(build, storage, size, corner, colors, occluded);
            Hashed(id, edit, build.Input);
            return shapes;
        };
    }

    private static byte[][] Build(
        ShapeBuild build,
        IMyStorage storage,
        Vector3I size,
        Vector3 corner,
        Vector3I[] colors,
        bool occluded
    )
    {
        // The levels read from the storage, from 8 up to the first that reads single voxels;
        // levels 4 and 2 are downsampled from 8
        var shapes = new byte[ImpostorEntry.Lods.Length][];
        var first = Array.IndexOf(ImpostorEntry.Lods, (byte)8);
        var levels = new List<(int index, int voxelLod)>();
        for (var i = first; i < shapes.Length; i++)
        {
            // The coarsest voxel level of detail with at least this many voxels along the longest axis
            var voxelLod = Math.Max(
                0,
                (int)Math.Floor(Math.Log(size.AbsMax() / (double)ImpostorEntry.Lods[i], 2))
            );
            levels.Add((i, voxelLod));
            if (voxelLod == 0)
                break;
        }

        // The voxels of every level first: they are what the shapes are built from, and the
        // same voxels reuse the shapes built before. The coarsest level is pooled from voxels
        // two levels finer, see below.
        var reads = new MyStorageData[levels.Count];
        var input = InputHash.Start((byte)ImpostorKind.Voxel);
        input.Add(size);
        input.Add(Vector3I.Round(corner * 16)); // Float noise of the matrix
        input.Add(occluded);
        foreach (var color in colors)
            input.Add(color);
        for (var k = levels.Count - 1; k >= 0; k--)
        {
            var voxelLod = levels[k].voxelLod;
            if (k == 0 && k < levels.Count - 1 && voxelLod > 0)
                voxelLod = Math.Max(0, voxelLod - 2);
            var voxels = Vector3I.Max(Vector3I.One, size >> voxelLod);
            var read = new MyStorageData();
            read.Resize(voxels);
            storage.ReadRange(
                read,
                MyStorageDataTypeFlags.ContentAndMaterial,
                voxelLod,
                Vector3I.Zero,
                voxels - 1
            );
            reads[k] = read;
            input.Add(read[MyStorageDataTypeEnum.Content], read.SizeLinear);
            input.Add(read[MyStorageDataTypeEnum.Material], read.SizeLinear);
        }
        var reused = build.Reuse(input);
        if (reused != null)
            return reused;

        // Finest first, for the extent of the content. The coarsest level is pooled from voxels
        // two levels finer, a cell filled when at least half of them are: the game's own
        // coarse voxels were eroded there, and level 8 looked half as large as level 16. It
        // also gets at least CoarsestCells cells across a rock that is small for its storage.
        var extent = 0f;
        CellVolume level8 = null;
        for (var k = levels.Count - 1; k >= 0; k--)
        {
            var (i, voxelLod) = levels[k];
            var cellSize = (float)(1 << voxelLod);
            var pooled = k == 0 && k < levels.Count - 1 && voxelLod > 0;
            if (pooled)
            {
                if (extent > 0)
                    cellSize = Math.Min(cellSize, extent / CoarsestCells);
                voxelLod = Math.Max(0, voxelLod - 2);
            }

            var voxels = Vector3I.Max(Vector3I.One, size >> voxelLod);
            var voxelSize = (float)(1 << voxelLod);
            var data = reads[k];
            reads[k] = null;

            var cells = Vector3I.Ceiling(new Vector3(size) / cellSize);
            var volume = new CellVolume(cells, cellSize, corner, ImpostorEntry.Lods[i]);
            var min = new Vector3I(int.MaxValue);
            var max = new Vector3I(int.MinValue);
            var p = Vector3I.Zero;
            for (p.Z = 0; p.Z < voxels.Z; p.Z++)
            for (p.Y = 0; p.Y < voxels.Y; p.Y++)
            for (p.X = 0; p.X < voxels.X; p.X++)
            {
                if (data.Content(ref p) <= MyVoxelConstants.VOXEL_ISO_LEVEL)
                    continue;
                volume.Add(
                    corner + (new Vector3(p) + 0.5f) * voxelSize,
                    colors[data.Material(ref p)]
                );
                min = Vector3I.Min(min, p);
                max = Vector3I.Max(max, p);
            }

            // A pooled cell is filled when at least half of its voxels are
            if (pooled)
                volume.DropBelow(
                    Math.Max(1, (int)Math.Round(Math.Pow(cellSize / voxelSize, 3) / 2))
                );
            if (extent == 0 && max.X >= min.X)
                extent = (max - min + 1).AbsMax() * voxelSize;
            shapes[i] = volume.ToShape(smooth: true, occluded);
            BuildTiming.Mark(ImpostorEntry.Lods[i], shapes[i]);
            if (i == first)
                level8 = volume;
        }

        // Far asteroids cover a few pixels, where only their color is left to see. A coarse
        // cell is filled when half of its 8 children are, which keeps the volume; a thin rock
        // that would vanish that way keeps every cell with a filled child.
        var coarse = level8;
        for (var i = first - 1; i >= 0 && coarse != null; i--)
        {
            var finer = coarse;
            coarse = finer.Downsample(ImpostorEntry.Lods[i], 4);
            shapes[i] = coarse.ToShape(smooth: true, occluded);
            if (shapes[i].Length <= Shape.HeaderSize)
            {
                coarse = finer.Downsample(ImpostorEntry.Lods[i], 1);
                shapes[i] = coarse.ToShape(smooth: true, occluded);
            }
            BuildTiming.Mark(ImpostorEntry.Lods[i], shapes[i]);
        }
        return shapes;
    }
}
